    local _b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local _lut_num = table.create(256, 0)
    for i = 1, #_b64 do
        _lut_num[string.byte(_b64, i)] = i - 1
    end

