    for i = 1, len, 4 do
        local c1, c2, c3, c4 = string.byte(_u_b64, i, i + 3)
        local a = _lut_num[c1] or 0
        local b = _lut_num[c2] or 0
        local c = _lut_num[c3] or 0
        local d = _lut_num[c4] or 0

        local b1 = bit32.bor(bit32.lshift(a, 2), bit32.rshift(b, 4))
        buffer.writeu8(buf, out_pos, b1)
        out_pos = out_pos + 1

        if c3 ~= 61 and out_pos < out_len then
            local b2 = bit32.bor(bit32.lshift(bit32.band(b, 15), 4), bit32.rshift(c, 2))
            buffer.writeu8(buf, out_pos, b2)
            out_pos = out_pos + 1
        end
        if c4 ~= 61 and out_pos < out_len then
            local b3 = bit32.bor(bit32.lshift(bit32.band(c, 3), 6), d)
            buffer.writeu8(buf, out_pos, b3)
            out_pos = out_pos + 1
        end
    end
    _u_buf = buf
    print("[Tanyx Scripts] Decoded bytecode buffer in Luau buffer: " .. tostring(out_len) .. " bytes")
end

