local _entry = _run_payload(_u_buf)
print("[Tanyx Scripts] VM closure resolved: " .. type(_entry))

if type(_entry) == "function" then
    print("[Tanyx Scripts] Spawning execution thread in non-blocking fiber...")
    task.spawn(function(...)
        local _success, _err = xpcall(_entry, function(e)
            return tostring(e) .. "\n" .. tostring(debug.traceback())
        end, ...)

        if not _success then
            warn("[Tanyx Scripts Exception]: " .. tostring(_err))
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Tanyx Error",
                    Text = tostring(_err):sub(1, 100),
                    Duration = 10
                })
            end)
        else
            print("[Tanyx Scripts] Execution fiber active.")
        end
    end)
else
    print("[Tanyx Scripts] Non-function return from payload: " .. tostring(_entry))
end
